/div><div class="mt-4 d-none" id="manualProof"><label class="form-label fw-bold">Payment proof</label><input type="file" name="proof" class="form-control" accept=".jpg,.jpeg,.png,.pdf"><div class="form-text">Upload a receipt after following the method instructions.</div></div></div></div><div class="col-xl-4"><div class="gsm-card p-4 position-sticky" style="top:92px"><h3 class="h5 fw-bold"><i class="fas fa-wallet text-primary me-2"></i>Order summary</h3><hr><div class="d-flex justify-content-between mb-2"><span class="text-muted">Amount</span><strong id="sumAmount">0.00</strong></div><div class="d-flex justify-content-between mb-2"><span class="text-muted">Fee</span><strong id="sumFee">0.00</strong></div><hr><div class="d-flex justify-content-between h5"><span>Total</span><strong id="sumTotal">0.00</strong></div><div class="d-flex justify-content-between text-success"><span>You receive</span><strong id="sumReceive">0.00</strong></div><button class="btn btn-gsm btn-lg w-100 mt-4" @disabled($gateways->isEmpty())>Continue securely <i class="fas fa-arrow-right ms-2"></i></button><div class="alert alert-primary small mt-3 mb-0"><i class="fas fa-shield-halved me-2"></i>Payments are verified securely. Never share a wallet private key.</div></div></div></div></form>@endif
@push('scripts')<script>const amount=document.getElementById('amount');function summary(){const a=parseFloat(amount?.value||0),g=document.querySelector('.gateway-choice:checked'),fixed=parseFloat(g?.dataset.fixed||0),pct=parseFloat(g?.dataset.percent||0),fee=fixed+a*pct/100;document.getElementById('sumAmount').textContent=a.toFixed(2);document.getElementById('sumFee').textContent=fee.toFixed(2);document.getElementById('sumTotal').textContent=(a+fee).toFixed(2);document.getElementById('sumReceive').textContent=a.toFixed(2);document.getElementById('manualProof').classList.toggle('d-none',g?.dataset.manual!=='1')}document.querySelectorAll('.amount-preset').forEach(b=>b.onclick=()=>{amount.value=b.dataset.value;summary()});document.querySelectorAll('.gateway-choice').forEach(r=>r.onchange=summary);amount?.addEventListener('input',summary);summary();</script>@endpush
